{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("missing required field")

    threshold = case["threshold"]
    calls = case["calls"]

    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not math.isfinite(threshold):
        raise ValueError("threshold must be finite")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    validated = []
    seen_ids = set()
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for call in calls:
        if not isinstance(call, dict) or any(field not in call for field in required):
            raise ValueError("invalid call structure")

        call_id = call["call_id"]
        without = call["loss_without_call"]
        with_call = call["loss_with_call"]
        tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if call_id in seen_ids:
            raise ValueError("duplicate call_id")
        seen_ids.add(call_id)
        if (isinstance(without, bool) or not isinstance(without, (int, float)) or
                isinstance(with_call, bool) or not isinstance(with_call, (int, float))):
            raise ValueError("losses must be numeric")
        if not math.isfinite(without) or not math.isfinite(with_call):
            raise ValueError("losses must be finite")
        if isinstance(tokens, bool) or not isinstance(tokens, int) or tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")

        validated.append((call_id, without, with_call, tokens, parseable))

    accepted_call_ids = []
    diagnostics = []
    for call_id, without, with_call, tokens, parseable in validated:
        normalized_gain = (without - with_call) / max(1, tokens)
        accepted = parseable and normalized_gain >= threshold
        rounded_gain = round(normalized_gain, 6)
        if rounded_gain == 0:
            rounded_gain = 0.0
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": rounded_gain,
        })
        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
